INSERT INTO `coa_client_spell_description` (`ID`, `Description`, `ToolTip`) VALUES
(806345, '$?a573338[|cffffffff][|cffff3232]Requires a Ranger\'s Horn or 5 Quick Shots|r\r\n|cff8fff7aGenerates 2 Advantage|r\r\nCall a cast of falcons to strike an enemy, dealing 121% Ranged Weapon Damage plus ${$m1+0} Nature damage and calling 1 |cffffffffWar Falcon|r to your aid for $520588d.\r\n\r\n@ext:Redirects all active summons to attack your target.:ext@', NULL),
